import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DIRECTIONS = ['매출', '매입'];
const TAX_TYPES = ['과세', '면세'];
// 가정: 승인번호 형식은 접두어 + 작성일(YYYYMMDD) + 일련번호 6자리
const APPROVAL_NO_PREFIX = 'TI';

function invalid(message: string): ApiError {
  return new ApiError(422, 'TAX_INVOICE_INVALID', message);
}

function amountOf(value: unknown, label: string): string {
  if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^\d+(\.\d{1,2})?$/.test(value.trim())) {
    return value.trim();
  }
  throw invalid(label + '은(는) 0 이상의 숫자여야 합니다.');
}

function idOf(value: unknown, label: string): string {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^\d+$/.test(value.trim())) {
    return value.trim();
  }
  throw invalid(label + '을(를) 확인해 주세요.');
}

@Controller('api/v1')
export class FnSfr00802Controller {
  @Post('/tax-invoices')
  @HttpCode(200)
  async issueTaxInvoice(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);

    const direction = data['direction'];
    if (typeof direction !== 'string' || !DIRECTIONS.includes(direction)) {
      throw invalid('매출/매입 구분을 확인해 주세요.');
    }
    const taxType = data['taxType'];
    if (typeof taxType !== 'string' || !TAX_TYPES.includes(taxType)) {
      throw invalid('과세·면세 구분을 확인해 주세요.');
    }
    const partnerId = idOf(data['partnerId'], '거래처');
    const issueDate = data['issueDate'];
    if (typeof issueDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(issueDate.trim())) {
      throw invalid('작성일자는 YYYY-MM-DD 형식이어야 합니다.');
    }
    const supplyAmount = amountOf(data['supplyAmount'], '공급가액');
    const taxAmount = amountOf(data['taxAmount'], '세액');
    // 가정: 면세는 세액 0
    if (taxType === '면세' && Number(taxAmount) !== 0) {
      throw invalid('면세는 세액이 0이어야 합니다.');
    }
    const items = data['items'];
    if (items !== undefined && items !== null && typeof items !== 'string') {
      throw invalid('거래 품목 형식이 올바르지 않습니다.');
    }

    return transaction(async (db) => {
      const partners = await db.query(
        'SELECT partner_id FROM partner WHERE partner_id = CAST(:partnerId AS bigint)',
        { partnerId },
      );
      if (partners.length === 0) {
        throw invalid('등록되지 않은 거래처입니다.');
      }

      // 채번 중복 방지: 같은 트랜잭션 구간에서 번호 생성을 직렬화한다
      await db.query('SELECT pg_advisory_xact_lock(8002)', {});
      const numbers = await db.query(
        'SELECT CAST(:prefix AS text) || to_char(CAST(:issueDate AS date), \'YYYYMMDD\') || \'-\' || lpad(CAST(COUNT(*) + 1 AS text), 6, \'0\') AS "approvalNo" '
          + 'FROM tax_invoice WHERE approval_no LIKE CAST(:prefix AS text) || to_char(CAST(:issueDate AS date), \'YYYYMMDD\') || \'-%\'',
        { prefix: APPROVAL_NO_PREFIX, issueDate: issueDate.trim() },
      );
      const approvalNo = String(numbers[0]['approvalNo']);

      // 가정: 국세청 발행 성공으로 보고 issued = true, verified = false
      const rows = await db.query(
        'INSERT INTO tax_invoice (approval_no, partner_id, direction, tax_type, issue_date, supply_amount, tax_amount, verified, issued, created_at, updated_at) '
          + 'VALUES (:approvalNo, CAST(:partnerId AS bigint), :direction, :taxType, CAST(:issueDate AS date), CAST(:supplyAmount AS numeric), CAST(:taxAmount AS numeric), false, true, now(), now()) '
          + 'RETURNING tax_invoice_id AS "taxInvoiceId", approval_no AS "approvalNo", issued AS "issued"',
        {
          approvalNo,
          partnerId,
          direction,
          taxType,
          issueDate: issueDate.trim(),
          supplyAmount,
          taxAmount,
        },
      );
      return rows[0];
    });
  }
}

