import { useState } from 'react';
import {
  call,
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
  Select,
  Tiles,
  TextInput,
} from '../kit';
import type { PageProps, Row } from '../kit';

const DIRECTIONS: [string, string][] = [['매출', '매출'], ['매입', '매입']];
const TAX_TYPES: [string, string][] = [['과세', '과세'], ['면세', '면세']];

export default function FnSfr00802Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [direction, setDirection] = useState('');
  const [partnerId, setPartnerId] = useState<unknown>('');
  const [issueDate, setIssueDate] = useState('');
  const [taxType, setTaxType] = useState('');
  const [supplyAmount, setSupplyAmount] = useState<unknown>('');
  const [taxAmount, setTaxAmount] = useState<unknown>('');
  const [items, setItems] = useState('');
  const [detail, setDetail] = useState<Row | null>(null);

  const reset = () => {
    setDirection('');
    setPartnerId('');
    setIssueDate('');
    setTaxType('');
    setSupplyAmount('');
    setTaxAmount('');
    setItems('');
  };

  const submit = async () => {
    if (!direction || !partnerId || !issueDate || !taxType) {
      throw new Error('매출/매입 구분, 거래처, 작성일자, 과세·면세 구분을 입력해 주세요.');
    }
    if (supplyAmount === '' || taxAmount === '') {
      throw new Error('공급가액과 세액을 입력해 주세요.');
    }
    const body: Row = {
      direction,
      partnerId,
      issueDate,
      taxType,
      supplyAmount,
      taxAmount,
    };
    if (items) {
      body.items = items;
    }
    const res = await call('POST', '/tax-invoices', role, body);
    const row: Row = { ...res, direction, partnerId, issueDate, taxType, supplyAmount, taxAmount };
    setResults([row, ...results]);
    setOpen(false);
    reset();
    notify('전자세금계산서를 발행했습니다.');
  };

  const issuedCount = results.filter((r) => r.issued === true).length;

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>이번 발행</h2>
        <Tiles items={[['발행 건수', <Num value={issuedCount} />]]} />
      </section>
      <section className='box span-8'>
        <h2>발행 내역</h2>
        <Band total={results.length}>
          <button type='button' onClick={() => setOpen(true)}>세금계산서 발행</button>
        </Band>
        <DataTable
          rows={results}
          empty='이 화면에서 발행한 내역이 없습니다.'
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'approvalNo', label: '승인번호' },
            { key: 'direction', label: '매출/매입 구분' },
            { key: 'partnerId', label: '거래처', render: (r) => <RefName table='partner' role={role} value={r.partnerId} /> },
            { key: 'issueDate', label: '작성일자', render: (r) => <DateText value={r.issueDate} /> },
            { key: 'supplyAmount', label: '공급가액', render: (r) => <Num value={r.supplyAmount} /> },
            { key: 'taxAmount', label: '세액', render: (r) => <Num value={r.taxAmount} /> },
            { key: 'issued', label: '발행 여부', render: (r) => <Badge value={r.issued === true ? '완료' : '대기'} /> },
          ]}
        />
      </section>
      {open && (
        <Drawer title='전자세금계산서 발행' onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit='발행'>
            <Field label='매출/매입 구분' required>
              <Select value={direction} onChange={setDirection} options={DIRECTIONS} />
            </Field>
            <Field label='거래처 ID' required>
              <LookupSelect table='partner' role={role} value={partnerId} onChange={setPartnerId} />
            </Field>
            <Field label='작성일자' required>
              <DateInput value={issueDate} onChange={setIssueDate} />
            </Field>
            <Field label='과세·면세 구분' required>
              <Select value={taxType} onChange={setTaxType} options={TAX_TYPES} />
            </Field>
            <Field label='공급가액' required>
              <NumberInput value={supplyAmount} onChange={setSupplyAmount} />
            </Field>
            <Field label='세액' required>
              <NumberInput value={taxAmount} onChange={setTaxAmount} />
            </Field>
            <Field label='거래 품목' wide>
              <TextInput value={items} onChange={setItems} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {detail && (
        <Drawer title='발행 결과' onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['승인번호', String(detail.approvalNo ?? '')],
              ['매출/매입 구분', String(detail.direction ?? '')],
              ['거래처', <RefName table='partner' role={role} value={detail.partnerId} />],
              ['작성일자', <DateText value={detail.issueDate} />],
              ['과세·면세 구분', String(detail.taxType ?? '')],
              ['공급가액', <Num value={detail.supplyAmount} />],
              ['세액', <Num value={detail.taxAmount} />],
              ['발행 여부', <Badge value={detail.issued === true ? '완료' : '대기'} />],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
